                SA = SA - SA.mean(1, keepdims=True); SB = SB - SB.mean(1, keepdims=True)   # centre per query row
                scale = np.abs(SA).mean() + 1e-9
                dA = (np.trace(SA)/10 - (SA.sum()-np.trace(SA))/90)/scale
